import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
} from '@angular/core';
import {
  presentCaseDetails,
  presentSetupData,
  homePresentDetail,
  TypeRes,
} from '../../../interfaces/presentsetup';
import { PresentsetupService } from '../../../services/presentsetup/presentsetup.service';
import { PresentListComponent } from '../present-list/present-list.component';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { ActivatedRoute, Router } from '@angular/router';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { LocationStrategy } from '@angular/common';
import { HeaderService } from '../../../../core/services/header/header.service';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';
import { UserDetail } from '../../../../core/interfaces/login.interface';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';

@Component({
  selector: 'presenthome',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [PresentListComponent],
  templateUrl: './presenthome.component.html',
  styleUrl: './presenthome.component.scss',
})
export class PresenthomeComponent {
  presentTypes: TypeRes[] = [];
  presentDetail: homePresentDetail;
  presentSession: presentSetupData;
  nCaseid: string;
  // previousSessionUUid: string;
  caseDetails: presentCaseDetails = {} as presentCaseDetails;

  userdetail: UserDetail;
  constructor(
    private readonly PSservice: PresentsetupService,
    private cm: CommonfunctionService,
    private route: ActivatedRoute,
    private cdr: ChangeDetectorRef,
    private tost: TostbarService,
    private location: LocationStrategy,
    private hs: HeaderService,
    private userPermissions: UserPermissionService, private ss: SecureStorageService,
  ) {
    var params = this.route.snapshot.params;
    params = JSON.parse(decodeURIComponent(params['id']));
    this.nCaseid = params && params['id'] ? params['id'] : null;
    hs.nCaseid = this.nCaseid;

    history.pushState(null, null, window.location.href);
    // check if back or forward button is pressed.
    this.location.onPopState(() => {
      history.pushState(null, null, window.location.href);
    });
    userPermissions.userPermissionList(this.nCaseid);

  }

  ngOnInit() {
    // check if caseadmin
    // this.previousSessionUUid = await this.PSservice.getPreviousUUID(this.nCaseid);
    this.initilise();
  }

  async initilise() {
    try {
      this.userdetail = await this.ss.getUserInfo();
      this.caseDetails = await this.PSservice.caseDetail(this.nCaseid);

      if (!this.userdetail?.isAdmin && !this.caseDetails?.permisson) {
        this.cm.gotoUrl('/user/dashboard');
        return;
      }
      this.presentTypes = await this.PSservice.getTypes();

      this.presentSession = await this.PSservice.getRvalue(this.nCaseid);
      await this.getPresentDetail();
    } catch (error) {
      console.error('Error initializing presentation home:', error);
    } finally {
      this.cdr.detectChanges();
    }
  }

  async setup(item) {
    // let cUUid: string = this.previousSessionUUid || this.PSservice.generateRandomId();
    let data: presentSetupData = {
      nCaseid: this.nCaseid,
      nTypeid: item.nValue,
      cType: item.jOther.type,
    };

    if (this.presentSession?.nTypeid != data.nTypeid) {
      data = { ...data, cName: '', cSType: '', jUsers: [], nSTypeid: 0 };
    }

    if (data?.cType == 'G' && this.presentDetail?.nPublicid) {
      this.tost.openSnackBar(
        'Global presentation already created can not create new one',
        'E'
      );
      return;
    } else if (data?.cType == 'P' && this.presentDetail?.nPrivateid) {
      this.tost.openSnackBar(
        'Private presentation already created can not create new one',
        'E'
      );
      return;
    }
    await this.PSservice.setRvalue(data);
    if (data.cType == 'G') {
      this.cm.gotoUrl('/present/subtype', { id: this.nCaseid });
    } else if (data.cType == 'P') {
      this.cm.gotoUrl('/present/setup', { id: this.nCaseid });
    }
  }

  async getPresentDetail() {
    this.presentDetail = await this.PSservice.getPresentHomeDetail(
      this.nCaseid
    );
    this.cdr.detectChanges();
  }

  refetch(e: any) {
    if (e == 'refetch') {
      this.getPresentDetail();
    }
  }
}
